PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `affixes` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`entry_id` integer NOT NULL,
	`term` text NOT NULL,
	`meaning_ms` text NOT NULL,
	`meaning_en` text,
	FOREIGN KEY (`entry_id`) REFERENCES `entries`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `dialects` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`entry_id` integer NOT NULL,
	`locality_name` text NOT NULL,
	`dialect_form` text NOT NULL,
	FOREIGN KEY (`entry_id`) REFERENCES `entries`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `entries` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`headword` text NOT NULL,
	`search_normalized` text NOT NULL,
	`part_of_speech` text NOT NULL,
	`ipa` text,
	`audio_url` text,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `examples` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`sense_id` integer NOT NULL,
	`sentence_bajau` text NOT NULL,
	`highlight_word` text,
	`sentence_ms` text NOT NULL,
	`sentence_en` text,
	`audio_url` text,
	FOREIGN KEY (`sense_id`) REFERENCES `senses`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `senses` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`entry_id` integer NOT NULL,
	`order_index` integer DEFAULT 1 NOT NULL,
	`definition_ms` text NOT NULL,
	`definition_en` text,
	FOREIGN KEY (`entry_id`) REFERENCES `entries`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `sources` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`entry_id` integer NOT NULL,
	`source_type` text NOT NULL,
	`description` text NOT NULL,
	`verified_by` text,
	FOREIGN KEY (`entry_id`) REFERENCES `entries`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `submissions` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`headword` text NOT NULL,
	`meaning` text NOT NULL,
	`example_sentence` text,
	`locality` text,
	`contributor_name` text,
	`contributor_email` text,
	`notes` text,
	`status` text DEFAULT 'pending' NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `thesaurus` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`entry_id` integer NOT NULL,
	`related_headword` text NOT NULL,
	`relation_note` text,
	FOREIGN KEY (`entry_id`) REFERENCES `entries`(`id`) ON UPDATE no action ON DELETE cascade
);
DELETE FROM sqlite_sequence;
CREATE INDEX `affixes_entry_id_idx` ON `affixes` (`entry_id`);
CREATE INDEX `affixes_term_idx` ON `affixes` (`term`);
CREATE INDEX `affixes_meaning_ms_idx` ON `affixes` (`meaning_ms`);
CREATE INDEX `dialects_entry_id_idx` ON `dialects` (`entry_id`);
CREATE INDEX `dialects_dialect_form_idx` ON `dialects` (`dialect_form`);
CREATE INDEX `entries_headword_idx` ON `entries` (`headword`);
CREATE INDEX `entries_search_normalized_idx` ON `entries` (`search_normalized`);
CREATE INDEX `examples_sense_id_idx` ON `examples` (`sense_id`);
CREATE INDEX `senses_entry_id_idx` ON `senses` (`entry_id`);
CREATE INDEX `senses_def_ms_idx` ON `senses` (`definition_ms`);
CREATE INDEX `senses_def_en_idx` ON `senses` (`definition_en`);
CREATE INDEX `sources_entry_id_idx` ON `sources` (`entry_id`);
CREATE INDEX `submissions_status_idx` ON `submissions` (`status`);
CREATE INDEX `thesaurus_entry_id_idx` ON `thesaurus` (`entry_id`);
